 imaging=img([view("axial", 48, 10, 30, "frontal operculum and precentral gyrus"), view("coronal", 50, 0, 35, "central sulcus region, face and hand areas")],
     "The superior trunk appears on CTA as the larger of the two M2 branches leaving the bifurcation, arching upward over the insula. Its cortical territory is the frontal and anterior parietal convexity above the Sylvian fissure.",
     [pathol("Superior division MCA infarct", "MRI", "Restricted diffusion in the inferior and middle frontal gyri, precentral and postcentral gyri and anterior insula, sparing the temporal lobe and the posterior parietal cortex; the basal ganglia are spared because the lenticulostriates arise from M1.", sequence="DWI")],
     "DWI; CTA to distinguish a branch occlusion from an M1 occlusion (which would add the lenticulostriate territory)"),
 lesion=[("Face and arm weakness with relative sparing of the leg", "contralateral", "Precentral gyrus opercular and hand areas"), ("Cortical sensory loss of the face and arm", "contralateral", "Postcentral gyrus"), ("Broca (non-fluent) aphasia with preserved comprehension", "n/a", "Inferior frontal gyrus of the dominant hemisphere"), ("Gaze preference toward the lesion", "ipsilateral", "Frontal eye field"), ("Motor neglect and anosognosia (non-dominant)", "contralateral", "Right frontal-parietal opercular cortex")],
 exam=["Test speech output (fluency, naming, repetition) against comprehension of commands", "Pronator drift and finger tapping versus hip flexion", "Observe conjugate gaze deviation and test saccades to the contralateral side"],
