 imaging=img([view("sagittal", 0, -26, -28, "basilar trunk on the clivus in front of the pons"), view("axial", 0, -26, -28, "midline flow void in the prepontine cistern"), view("axial", 0, -20, -10, "basilar tip in the interpeduncular cistern")],
     "A single midline flow void in front of the pons on every axial T2 slice through the pons and a smooth tube on sagittal T1. On non-contrast CT the artery lies on the clivus; a dense basilar suggests acute thrombus. CTA shows the whole vessel from the vertebral confluence to the tip.",
     [pathol("Basilar artery occlusion", "CTA", "Absent contrast in a segment of the basilar with bilateral pontine, cerebellar, thalamic and occipital infarcts on DWI depending on the level; the hyperdense basilar sign on plain CT is an early clue.", sequence="CT contrast", timing="Hyperdense basilar visible at once; DWI lesions evolve over hours; recanalisation therapy is time-critical"),
      pathol("Pontine paramedian infarct", "MRI", "A wedge of restricted diffusion in one paramedian half of the pons reaching the ventral surface, from branch atheromatous disease of a paramedian perforator.", sequence="DWI"),
      pathol("Basilar tip aneurysm", "CTA", "Saccular aneurysm at the bifurcation projecting upward into the interpeduncular cistern; may compress the oculomotor nerves or the midbrain.", sequence="CT contrast")],
     "CTA immediately when a brainstem stroke is suspected; DWI for extent; DSA for treatment planning"),
 lesion=[("Quadriparesis with preserved consciousness and vertical eye movements (locked-in)", "bilateral", "Bilateral ventral pontine infarction sparing the tegmentum and midbrain"), ("Crossed syndromes: ipsilateral cranial nerve palsy with contralateral hemiparesis", "contralateral", "Unilateral paramedian pontine infarct catching the abducens or facial nucleus/fascicle and the corticospinal tract"), ("Coma, pinpoint pupils, ophthalmoplegia", "bilateral", "Pontine tegmentum and reticular activating system"), ("Top-of-the-basilar syndrome: somnolence, vertical gaze palsy, hallucinations, hemianopia", "bilateral", "Embolus at the bifurcation involving thalamus, midbrain and occipital lobes")],
 exam=["Assess consciousness, pupils, corneal reflexes and eye movements in every stuporous patient", "Look for bilateral long-tract signs", "Ask about preceding vertigo, diplopia, dysarthria and drop attacks (basilar TIAs)"],
 pearls=["Bilateral or crossed signs with altered consciousness mean the basilar artery until proven otherwise; call for CTA", "Locked-in patients are awake: examine vertical eye movements and blinking before assuming coma"],
